def generate(rng):
    H=W=10
    g=[[0]*W for _ in range(H)]
    colors=rng.sample([1,2,3,4,5,6,7,8,9],3)
    # Place three non-overlapping instances of a 3x3 L-like marker:
    # top row has endpoints at local cols 0 and 3, lower two rows are 2x2 at cols 1,2.
    placements=[(0, rng.choice([0,1,2,3,4,5,6])),
                (rng.choice([3,4,5,6,7]), rng.choice([0,1,2,3,4,5,6])),
                (rng.choice([3,4,5,6,7]), rng.choice([0,1,2,3,4,5,6]))]
    # retry placements to avoid overlap, while retaining varied locations
    for k,(r,c) in enumerate(placements):
        if any(g[rr][cc] for rr in range(r,min(r+3,10)) for cc in range(c,min(c+4,10))):
            for rr in range(8):
